<template>
<PageHeader title="Dashboard" subtitle="Overview of the IT support environment." ><RouterLink class="btn primary" to="/tickets">+ New Ticket</RouterLink></PageHeader>
<div class="stats"><div class="stat"><span>Open Tickets</span><strong>3</strong><em>Needs attention</em></div><div class="stat"><span>Pending</span><strong>2</strong><em>Waiting for action</em></div><div class="stat"><span>Resolved</span><strong>18</strong><em>This month</em></div><div class="stat"><span>Devices</span><strong>48</strong><em>5 offline</em></div></div>
<div class="grid-2"><section class="panel"><div class="panel-head"><h2>Recent Tickets</h2><RouterLink to="/tickets">View all</RouterLink></div><div v-for="t in tickets.slice(0,5)" :key="t.id" class="ticket-row"><div class="ticket-icon">{{ t.category[0] }}</div><div class="grow"><RouterLink :to="'/tickets/'+t.id"><strong>{{ t.title }}</strong></RouterLink><small>{{ t.id }} · {{ t.requester }} · {{ t.updated }}</small></div><span :class="['badge', t.status.toLowerCase()]">{{ t.status }}</span></div></section>
<section class="panel"><div class="panel-head"><h2>System Status</h2><span class="live">● Live</span></div><div class="status-line"><span>Apache Web Server</span><strong class="online">Online</strong></div><div class="status-line"><span>Network Gateway</span><strong class="online">Online</strong></div><div class="status-line"><span>Moodle Server</span><strong class="online">Online</strong></div><div class="status-line"><span>Backup Server</span><strong class="offline">Offline</strong></div></section></div>
</template>
<script setup>import PageHeader from '../components/PageHeader.vue'; import { tickets } from '../data/data.js'</script>
